// 1. Girdi Alımı
const veri = $input.first().json;

const adSoyad = veri['Ad Soyad'];
const eposta = veri['E-posta'];
const aylikGelir = Number(veri['Aylık Gelir']);
const mevcutBorc = Number(veri['Mevcut Aylık Borç']);
const krediTutari = Number(veri['İstenen Kredi Tutarı']);
const vade = Number(veri['Vade (Ay)']);

// 2. Finansal Hesaplama (Basit Faiz)
const faizOrani = 0.035;
const toplamGeriOdeme = krediTutari * (1 + faizOrani * vade);
const yeniAylikTaksit = toplamGeriOdeme / vade;
const toplamAylikBorc = mevcutBorc + yeniAylikTaksit;
const borcGelirOrani = (toplamAylikBorc / aylikGelir) * 100;

// 3. Karar Mekanizması
let durum = '';
if (borcGelirOrani <= 50) {
  durum = 'ÖN ONAY';
} else {
  durum = 'RED';
}

return [
  {
    json: {
      Ad_Soyad: adSoyad,
      Eposta: eposta,
      Aylik_Gelir: aylikGelir,
      Mevcut_Borc: mevcutBorc,
      Kredi_Tutari: krediTutari,
      Vade: vade,
      Toplam_Geri_Odeme: Math.round(toplamGeriOdeme),
      Yeni_Aylik_Taksit: Math.round(yeniAylikTaksit),
      Toplam_Aylik_Borc: Math.round(toplamAylikBorc),
      Borc_Gelir_Orani: Number(borcGelirOrani.toFixed(2)),
      Durum: durum
    }
  }
];
